Write Jest test suite for TypedEmitter class
Write `emitter.test.ts` — a Jest test suite for the `TypedEmitter` class described below.

## The class under test
```typescript
// emitter.ts
export class TypedEmitter<Events extends Record<string, unknown[]>> {
  on<K extends keyof Events>(event: K, listener: (...args: Events[K]) => void): this
  off<K extends keyof Events>(event: K, listener: (...args: Events[K]) => void): this
  emit<K extends keyof Events>(event: K, ...args: Events[K]): boolean
  once<K extends keyof Events>(event: K, listener: (...args: Events[K]) => void): this
  listenerCount<K extends keyof Events>(event: K): number
}
```

## Requirements
- Test: on/off/emit/once/listenerCount
- Edge cases: emit with no listeners (returns false), emit with listeners (returns true), once fires exactly once, off removes correct listener, multiple events are independent
- Minimum 12 test cases (use `it()` or `test()`).

## Deliverable
`emitter.test.ts`. Must pass: `npx jest emitter.test.ts`
{"instructions":"Write emitter.test.ts with Jest tests for TypedEmitter class from emitter.ts. Test on/off/emit/once/listenerCount. Cover: emit returns false with no listeners, true with listeners; once fires exactly once; off removes specific listener; multiple events independent; listenerCount accurate. Minimum 12 test cases using describe/it or test blocks.","success_condition":{"type":"code_test","language":"bash","test_code":"#!/bin/bash
set -e

test -f emitter.test.ts || { echo "FAIL: emitter.test.ts not found"; exit 1; }

# Write emitter.ts implementation
cat > emitter.ts << 'EOF'
export class TypedEmitter<Events extends Record<string, unknown[]>> {
  private listeners: Map<keyof Events, Array<(...args: unknown[]) => void>> = new Map();

  on<K extends keyof Events>(event: K, listener: (...args: Events[K]) => void): this {
    if (!this.listeners.has(event)) this.listeners.set(event, []);
    this.listeners.get(event)!.push(listener as (...args: unknown[]) => void);
    return this;
  }

  off<K extends keyof Events>(event: K, listener: (...args: Events[K]) => void): this {
    const arr = this.listeners.get(event) || [];
    const idx = arr.indexOf(listener as (...args: unknown[]) => void);
    if (idx !== -1) arr.splice(idx, 1);
    return this;
  }

  emit<K extends keyof Events>(event: K, ...args: Events[K]): boolean {
    const arr = this.listeners.get(event) || [];
    if (arr.length === 0) return false;
    arr.slice().forEach(fn => fn(...args));
    return true;
  }

  once<K extends keyof Events>(event: K, listener: (...args: Events[K]) => void): this {
    const wrapper = (...args: unknown[]) => {
      this.off(event, listener);
      (listener as (...args: unknown[]) => void)(...args);
    };
    return this.on(event, wrapper as (...args: Events[K]) => void);
  }

  listenerCount<K extends keyof Events>(event: K): number {
    return (this.listeners.get(event) || []).length;
  }
}
EOF

# Write jest config + package if needed
if [ ! -f package.json ]; then
