```javascript
import { deepClone } from './deep_clone.js';

// Primitives
console.assert(deepClone(42) === 42);
console.assert(deepClone("hi") === "hi");
console.assert(deepClone(null) === null);

// Object isolation
const obj = { a: 1, b: { c: 2 } };
const cloned = deepClone(obj);
cloned.b.c = 99;
console.assert(obj.b.c === 2, "original should not mutate");

