#!/bin/bash
set -e

# Test that script exists and is runnable
test -f disk_check.sh || { echo "FAIL: disk_check.sh not found"; exit 1; }

# Mock df to return controlled output
df() {
  echo "Filesystem      Size  Used Avail Use% Mounted on"
  echo "/dev/sda1        50G   42G  8G    85% /"
  echo "tmpfs           8.0G  100M 7.9G   2% /dev/shm"
  echo "/dev/sdb1        20G   19G  1G    95% /data"
}
export -f df

OUTPUT=$(bash disk_check.sh 80)

echo "$OUTPUT" | grep -q "ALERT: / is at 85% (threshold: 80%)" || {
  echo "FAIL: expected ALERT for / at 85%"
  echo "Got: $OUTPUT"
  exit 1
}
echo "$OUTPUT" | grep -q "ALERT: /data is at 95% (threshold: 80%)" || {
  echo "FAIL: expected ALERT for /data at 95%"
  echo "Got: $OUTPUT"
  exit 1
}
echo "$OUTPUT" | grep -qv "ALERT.*shm|ALERT.*2%" || true  # tmpfs at 2% should NOT alert

# Test OK message when threshold is 100
df() {
  echo "Filesystem      Size  Used Avail Use% Mounted on"
  echo "/dev/sda1        50G   10G 40G    20% /"
}
export -f df
OUTPUT2=$(bash disk_check.sh 100)
echo "$OUTPUT2" | grep -q "OK:" || {
  echo "FAIL: expected OK message when all below threshold"
  echo "Got: $OUTPUT2"
  exit 1
}

echo "ALL TESTS PASSED"

import fizzBuzz from './fizzbuzz.js';
import assert from 'assert';

// Classic FizzBuzz
const result = fizzBuzz(15, [[3, "Fizz"], [5, "Buzz"]]);
assert.deepStrictEqual(result, ["1","2","Fizz","4","Buzz","Fizz","7","8","Fizz","Buzz","11","Fizz","13","14","FizzBuzz"]);

// Single rule
assert.deepStrictEqual(fizzBuzz(6, [[2, "Even"]]), ["1","Even","3","Even","5","Even"]);

// No matches → numbers as strings
assert.deepStrictEqual(fizzBuzz(3, [[7, "Seven"]]), ["1","2","3"]);

// n=1
assert.deepStrictEqual(fizzBuzz(1, [[3,"Fizz"],[5,"Buzz"]]), ["1"]);

// Multiple concatenation order matters
const r2 = fizzBuzz(30, [[3,"Fizz"],[5,"Buzz"],[2,"Bang"]]);
assert.strictEqual(r2[5], "FizzBang");  // 6 divisible by 3 and 2
assert.strictEqual(r2[29], "FizzBuzzBang"); // 30 divisible by 3,5,2

console.log("ALL TESTS PASSED");
